import React from "react";
import { HashRouter, Routes, Route, Link } from "react-router-dom"
import "./App.css";
import BlurHome from "./defaultresort/mainhome/blurHome";
impo
import Navigation from "./defaultresort/navigationpage";
// import MainHome from "./defaultresort/mainhome/mainhome";
const LazyMainHome = React.lazy( () => import("./defaultresort/mainhome/mainhome") )


function App() {
  return (
    <HashRouter>
      <Navigation />
      <Routes>
        <Route path="/" element={
          <React.Suspense fallback={<BlurHome />} >
            <LazyMainHome />
          </React.Suspense>
        } />
      </Routes>
    </HashRouter>
  );
}

export default App;
